'use client';

import { cookies } from 'next/headers';
import { NextRequest } from 'next/server';
import { useState, useEffect } from 'react';

interface ThemePreferencesProps {
  request?: NextRequest;
}

export default function ThemePreferences({ request }: ThemePreferencesProps) {
  const [theme, setTheme] = useState<string>('light');
  const [language, setLanguage] = useState<string>('');

  useEffect(() => {
    // Read theme from cookie
    const themeCookie = document.cookie
      .split('; ')
      .find(row => row.startsWith('theme='))
      ?.split('=')[1];

    if (themeCookie) {
      setTheme(themeCookie);
    }

    // Read language from Accept-Language header (would need server-side prop)
    if (request) {
      setLanguage(request.headers.get('accept-language') || 'Not specified');
    }
  }, [request]);

  return (
    <div style={{ padding: '20px', border: '1px solid #ccc', borderRadius: '8px', margin: '20px 0' }}>
      <h3>Theme Preferences</h3>
      <div style={{ marginBottom: '10px' }}>
        <strong>Current Theme:</strong> {theme}
      </div>
      <div>
        <strong>Preferred Language:</strong> {language || 'Not specified'}
      </div>
    </div>
  );
}

